+  @Test
+  public void legacyCompatOutputsSameJsonAsRtaf(
+      @TestParameter(valuesProvider = RtafToLegacyCompatProvider.class) Message message,
+      @TestParameter({
+            "IDENTITY",
+            "UPPER_CAMEL_CASE",
+            "UPPER_CASE_WITH_UNDERSCORES",
+            "LOWER_CASE_WITH_UNDERSCORES",
+            "LOWER_CASE_WITH_DASHES"
