+  @Test
+  public void legacyCompatToRtafWithTargetTypeMessage(
+      @TestParameter(valuesProvider = LegacyCompatToRtafProvider.class) Message message) {
+    String json = GSON_WITH_LEGACY_ADAPTER.toJson(message, Message.class);
