+   * type.
+   */
+  @Test
+  public void rtafToLegacyCompatWithTargetTypeMessage(
+      @TestParameter(valuesProvider = LegacyCompatToRtafProvider.class) Message message) {
+    String json = RTAF_GSON.toJson(message);
